// @whimtex-effect Samples/Bubble Highlight
// @control(_Opacity)
// @param hidden float _Opacity = 1 [0 .. 1]
// @param point _Center = (0.292, 0.633)
// @param float _Size = 0.029 [0.005 .. 0.15]
// @param float _Halo = 0.25 [0 .. 1]

float4 ApplyFX(float2 uv,float4 color){
    float d=length(uv-_Center)/max(_Size,.001);
    float core=exp(-pow(d,4)*1.5);
    float halo=exp(-d*d*.32)*_Halo;
    float clip=1-smoothstep(.382,.390,length(uv-.5));
    return float4(1,1,1,saturate(core+halo)*_Opacity*clip);
}

