// @whimtex-effect Samples/Bubble Rim
// @control(_Opacity)
// @param hidden float _Opacity = 1 [0 .. 1]
// @param float _Radius = 0.39 [0.1 .. 0.45]
// @param float _Width = 0.014 [0.002 .. 0.06]
// @param float _Softness = 0.032 [0.005 .. 0.1]

float4 ApplyFX(float2 uv,float4 color){
    float2 p=uv-.5;
    float r=length(p);
    float inset=_Radius-r;
    float outer=smoothstep(-.003,.003,inset);
    float ring=exp(-pow((inset-.008)/_Width,2));
    float soft=exp(-max(inset,0)/_Softness)*.60;
    float angle=dot(p/max(r,.0001),normalize(float2(-.7,1)));
    float alpha=outer*saturate(max(ring,soft)*(.82+.18*angle))*_Opacity;
    return float4(1,1,1,alpha);
}

// @whimtex-effect Samples/Bubble Reflection
// @control(_Opacity)
// @param hidden float _Opacity = 0.5 [0 .. 1]
// @param float _Radius = 0.39 [0.1 .. 0.45]
// @param float _Depth = 0.085 [0.01 .. 0.2]

float4 ApplyFX(float2 uv,float4 color){
    float2 p=uv-.5;
    float r=length(p);
    float edge=1-smoothstep(_Radius-.007,_Radius,r);
    float2 direction=p/max(r,.0001);
    float lower=pow(saturate(dot(direction,normalize(float2(.50,-1)))*.5+.5),3);
    float upper=pow(saturate(dot(direction,normalize(float2(-.6,1)))*.5+.5),5);
    float depth=exp(-pow((r-(_Radius-.045))/_Depth,2));
    float reflection=depth*(.75*lower+.30*upper);
    return float4(1,1,1,saturate(reflection*_Opacity*edge));
}
